# ======================== 写入 CSV ========================

disease_fields = ["疾病名称", "ICD-11编码", "上级分类路径", "疾病描述", "临床体征/症状", "排除项", "详情页URL"]
drug_fields = ["产品名称", "英文名称", "批准文号", "生产单位", "剂型", "规格", "适应症", "药品分类", "批准日期", "有效期", "详情页URL"]

# 疾病 CSV
d_path = os.path.join(OUTPUT_DIR, "diseases.csv")
with open(d_path, "w", newline="", encoding="utf-8-sig") as f:
    writer = csv.DictWriter(f, fieldnames=disease_fields, quoting=csv.QUOTE_ALL)
    writer.writeheader()
    writer.writerows(diseases)
print(f"✓ 生成 diseases.csv: {len(diseases)} 条疾病数据")

# 药品 CSV
dr_path = os.path.join(OUTPUT_DIR, "drugs.csv")
with open(dr_path, "w", newline="", encoding="utf-8-sig") as f:
    writer = csv.DictWriter(f, fieldnames=drug_fields, quoting=csv.QUOTE_ALL)
    writer.writeheader()
    writer.writerows(drugs)
print(f"✓ 生成 drugs.csv: {len(drugs)} 条药品数据")

print(f"\n文件位置: {os.path.abspath(d_path)}")
print(f"文件位置: {os.path.abspath(dr_path)}")
